// Garde le client dont le code, le nom ou un alias est CONTENU dans le titre de la vidéo.
// Aucun client trouvé : on applique le style « Par défaut » (ligne code = default) au lieu de s'arrêter.
const title = $('Extraire le client du titre').first().json.title || '';
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const t = norm(title);
let best = null;
let bestLen = 0;
let bestTerm = '';
for (const item of $input.all()) {
  const c = item.json;
  if (!c || !c.code) continue;
  const terms = [c.code, c.nom, ...(Array.isArray(c.alias) ? c.alias : [])];
  for (const term of terms) {
    const n = norm(term);
    if (n.length >= 3 && t.includes(n) && n.length > bestLen) {
      best = c;
      bestLen = n.length;
      bestTerm = term;
    }
  }
}
if (!best) {
  const defaut = $input.all().map((i) => i.json).find((c) => c && c.code === 'default');
  if (defaut) return [{ json: { ...defaut, matched_term: '', inconnu: true } }];
}
// Ni client ni style par défaut : un item vide pour que « Client connu ? » prenne la branche alerte.
return [{ json: best ? { ...best, matched_term: bestTerm } : {} }];

