  const fin = subs.reduce((m, s) => Math.max(m, Number(s.end) || 0), 0);
  const min = Math.floor(fin / 60);
  const sec = Math.round(fin % 60);
  const duree = min > 0 ? min + ' min ' + String(sec).padStart(2, '0') + ' s' : sec + ' s';
  const cl = $('Lire le client pour le mail').first().json || {};
  const code = b.client_code || cl.code || '';
  const defaut = code === 'default';
  const style = defaut ? 'Style par défaut (aucune marque reconnue dans le titre)' : esc(cl.nom || cl.menu_label || code);
  const genres = {};
  subs.forEach((s) => { if (s.genre) { genres[s.genre] = (genres[s.genre] || 0) + 1; } });
  const liste = Object.keys(genres).map((g) => g + ' : ' + genres[g]).join(', ');
  const nImpact = subs.filter((s) => Array.isArray(s.impact) && s.impact.length > 0).length;
  const reprises = Math.max(0, Number(b.attempt || 1) - 1);
