    + '<p style="margin:20px 0"><a href="' + lien + '" style="background:#1a73e8;color:#ffffff;padding:12px 24px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block">Regarder la vidéo</a></p>'
    + '<h3 style="margin:24px 0 8px">Résumé du traitement</h3>'
