    + ligne('Variantes de style choisies', liste || 'aucune (style de la marque partout)')
    + ligne('Sous-titres avec mots en impact', nImpact)
    + '</table>'
    + '<h3 style="margin:24px 0 8px">Contrôle qualité</h3>'
    + '<p>' + verdict + ' Points vérifiés par le second agent sur 2 captures de la vidéo et sur le texte des sous-titres :</p>'
    + '<p style="line-height:1.7">' + controles.map((c) => '✓ ' + c).join('<br>') + '</p>'
    + '<p style="color:#666;font-size:13px">La vidéo et son fichier .srt sont aussi dans le dossier Drive <a href="' + dossier + '">Valider</a>.</p>'
    + (defaut ? '<p style="color:#b45309;font-size:13px">Aucune marque n’a été reconnue dans le titre : le style par défaut a été appliqué.</p>' : '')
