// Normalise la réponse du formulaire : action (arreter / continuer / creer), nom, alias, couleur.
const brut = $input.first().json || {};
const d = (brut.data && typeof brut.data === 'object') ? brut.data : brut;
let action = '';
let nom = '';
let alias = '';
let couleur = '';
for (const [k, v] of Object.entries(d)) {
  const cle = String(k).toLowerCase();
  const val = String(v == null ? '' : v).trim();
  if (cle.includes('que faire')) action = val;
  else if (cle.includes('alias')) alias = val;
  else if (cle.includes('couleur')) couleur = val;
  else if (cle.includes('nom')) nom = val;
}
const a = action.toLowerCase();
let choix = 'arreter';
if (a.includes('continuer')) choix = 'continuer';
else if (a.includes('créer')) choix = 'creer';
// Création demandée sans nom de marque : on continue avec le style par défaut plutôt que de bloquer.
const sansNom = choix === 'creer' && !nom;
if (sansNom) choix = 'continuer';
return [{ json: { action: choix, nom, alias: alias.split(/[,;]+/).map((s) => s.trim()).filter(Boolean), couleur, sans_nom: sansNom } }];

// Prépare la nouvelle ligne de la table Clients : copie du style par défaut, nom, alias et couleur de la marque.
const rep = $input.first().json;
const tous = $('Chercher le client').all().map((i) => i.json).filter((c) => c && c.code);
const defaut = tous.find((c) => c.code === 'default') || {};
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
let code = norm(rep.nom) || 'client';
const pris = new Set(tous.map((c) => String(c.code).toLowerCase()).concat(['default', 'corporate', 'impact', 'karaoke']));
while (pris.has(code)) code += '2';
const base = JSON.parse(JSON.stringify(typeof defaut.style === 'string' ? JSON.parse(defaut.style) : (defaut.style || {})));
base.client = rep.nom;
base.code = code.toUpperCase();
if (/^#[0-9a-fA-F]{6}$/.test(rep.couleur || '')) {
  base.couleurs = Object.assign({}, base.couleurs, { mot_cle_accent: rep.couleur });
  base.impact = Object.assign({}, base.impact, { couleur: rep.couleur });
}
return [{ json: { code, nom: rep.nom, menu_label: rep.nom, alias: JSON.stringify(rep.alias || []), style: JSON.stringify(base), glossaire: '[]', actif: 'true', skill_md: defaut.skill_md || '' } }];

// Le modèle de vision est limité à 7000 tokens d'entrée par minute : on ne garde que 2 captures (au tiers et aux deux tiers de la vidéo) et on retire les autres fichiers (report.json, etc.) qui seraient envoyés au modèle.
return $input.all().map((item) => {
  const bin = item.binary || {};
  const noms = Object.keys(bin).filter((k) => /^capture_\d+$/.test(k)).sort((a, b) => Number(a.slice(8)) - Number(b.slice(8)));
  const garder = noms.length <= 2 ? noms : [noms[Math.floor(noms.length / 3)], noms[Math.floor((2 * noms.length) / 3)]];
  const reste = {};
  for (const k of garder) { reste[k] = bin[k]; }
  return { json: item.json, binary: reste };
});
